const inItem = $input.first().json;
const body = (inItem && inItem.body) ? inItem.body : inItem;
function norm(s){ if(s===undefined||s===null) return ""; return String(s).toLowerCase().trim(); }
function num(s){ const n = Number(s); return isFinite(n) ? n : 0; }
function isSet(v){ return !(v===undefined||v===null||String(v).trim()===""); }

const DISC = "Indikativer Richtwert. Das genaue Angebot erhalten Sie per E-Mail, den Link zusaetzlich per SMS.";

const CATALOG = {
  car: [
    { ProductCode:"CAR-LIAB-STD", ProductName:"Unica Kfz Haftpflicht", base:480 },
    { ProductCode:"CAR-TK-COMFORT", ProductName:"Unica Kfz Komfort (Haftpflicht + Teilkasko)", base:760 },
    { ProductCode:"CAR-VK-PREMIUM", ProductName:"Unica Kfz Premium (Haftpflicht + Vollkasko)", base:1180 }
  ],
  liability: [
    { ProductCode:"LIAB-SINGLE", ProductName:"Unica Privathaftpflicht Single", base:70 },
    { ProductCode:"LIAB-FAMILY", ProductName:"Unica Privathaftpflicht Familie", base:95 }
  ],
  home_contents: [
    { ProductCode:"HC-STD", ProductName:"Unica Haushalt Standard", rate:0.0016 },
    { ProductCode:"HC-PLUS", ProductName:"Unica Haushalt Plus", rate:0.0022 }
  ],
  legal: [
    { ProductCode:"LEGAL-PRIVATE", ProductName:"Unica Rechtsschutz Privat", base:230 },
    { ProductCode:"LEGAL-COMBO", ProductName:"Unica Rechtsschutz Kombi", base:360 }
  ],
  life: [
    { ProductCode:"LIFE-TERM-STD", ProductName:"Unica Risikoleben", rate:0.0009 },
    { ProductCode:"LIFE-VORSORGE", ProductName:"Unica Leben Vorsorge", rate:0.0021 }
  ]
};

function mapLine(raw){
  const s = norm(raw);
  function has(arr){ for(var i=0;i<arr.length;i++){ if(s.indexOf(arr[i])>=0) return true; } return false; }
  if(has(["car","auto","kfz","pkw","fahrzeug","automobil"])) return "car";
  if(has(["haftpflicht","liability"])) return "liability";
  if(has(["hausrat","haushalt","home","contents","eigenheim","wohnung","inhalt"])) return "home_contents";
  if(has(["rechtsschutz","legal","recht"])) return "legal";
  if(has(["leben","life","vorsorge","risikoleben"])) return "life";
  return "";
}

function round10(n){ var r = Math.round(n/10)*10; return r < 10 ? 10 : r; }
function regionF(r){ var x = norm(r); if(x.indexOf("wien")>=0) return 1.15; if(x.indexOf("graz")>=0||x.indexOf("linz")>=0||x.indexOf("salzburg")>=0) return 1.07; return 1.0; }
function pick(line, code){ var arr = CATALOG[line]; for(var i=0;i<arr.length;i++){ if(arr[i].ProductCode===code) return arr[i]; } return arr[0]; }

const line = mapLine(body.line_of_business);

if(!line){
  return [{ json: {
    status:"Disqualified", line: norm(body.line_of_business)||"unknown",
    recommended_product:null, estimate:null, indicative_range:null,
    rationale:"Diese Versicherungsart wird aktuell nicht angeboten. Ich leite Sie an einen Spezialisten weiter, der zurueckruft.",
    missing_fields:[], next_step:"pass_to_specialist", offer_channel:null, disclaimer:DISC
  } }];
}

var prod=null, mid=0, missing=[], rationale="";

if(line==="car"){
  var cov=norm(body.coverage);
  if(!isSet(body.coverage)) missing.push("coverage");
  if(!isSet(body.driver_age)) missing.push("driver_age");
  if(!isSet(body.power_kw)) missing.push("power_kw");
  if(!isSet(body.region)) missing.push("region");
  if(missing.length===0){
    var code="CAR-LIAB-STD";
    if(cov.indexOf("vollkasko")>=0||cov.indexOf("voll")>=0) code="CAR-VK-PREMIUM";
    else if(cov.indexOf("teilkasko")>=0||cov.indexOf("teil")>=0) code="CAR-TK-COMFORT";
    prod=pick("car",code);
    var age=num(body.driver_age), power=num(body.power_kw), bm=num(body.bonus_malus); if(!bm) bm=1.0;
    var ageF=1.0;
    if(age<23)ageF=1.45; else if(age<25)ageF=1.30; else if(age<30)ageF=1.18; else if(age<40)ageF=1.06; else if(age<60)ageF=1.0; else if(age<70)ageF=1.12; else ageF=1.30;
    var powerF=1+Math.max(0,(power-70))*0.006;
    mid=prod.base*ageF*powerF*regionF(body.region)*bm;
    rationale=prod.ProductName+", "+age+" Jahre, "+power+" kW.";
  }
} else if(line==="liability"){
  if(!isSet(body.household)) missing.push("household");
  if(!isSet(body.region)) missing.push("region");
  if(missing.length===0){
    var fam=norm(body.household).indexOf("famil")>=0;
    prod=pick("liability", fam?"LIAB-FAMILY":"LIAB-SINGLE");
    mid=prod.base*(regionF(body.region)>1.1?1.05:1.0);
    rationale=prod.ProductName+".";
  }
} else if(line==="home_contents"){
  if(!isSet(body.contents_value)) missing.push("contents_value");
  if(!isSet(body.region)) missing.push("region");
  if(missing.length===0){
    var cv=num(body.contents_value), hcov=norm(body.coverage);
    prod=pick("home_contents",(hcov.indexOf("plus")>=0||hcov.indexOf("premium")>=0)?"HC-PLUS":"HC-STD");
    mid=cv*prod.rate*regionF(body.region);
    rationale=prod.ProductName+", Summe "+cv+" Euro.";
  }
} else if(line==="legal"){
  var lcov=norm(body.coverage);
  prod=pick("legal",(lcov.indexOf("kombi")>=0||lcov.indexOf("combo")>=0||lcov.indexOf("verkehr")>=0||lcov.indexOf("beruf")>=0)?"LEGAL-COMBO":"LEGAL-PRIVATE");
  mid=prod.base;
  rationale=prod.ProductName+".";
} else if(line==="life"){
  var hasAge=isSet(body.age)||isSet(body.driver_age);
  if(!hasAge) missing.push("age");
  if(!isSet(body.sum_assured)) missing.push("sum_assured");
  if(!isSet(body.term_years)) missing.push("term_years");
  if(!isSet(body.tobacco)) missing.push("tobacco");
  if(missing.length===0){
    var vcov=norm(body.coverage);
    prod=pick("life",(vcov.indexOf("vorsorge")>=0||vcov.indexOf("spar")>=0||vcov.indexOf("erleben")>=0)?"LIFE-VORSORGE":"LIFE-TERM-STD");
    var lage=num(isSet(body.age)?body.age:body.driver_age);
    var sa=num(body.sum_assured), term=num(body.term_years);
    var lifeAgeF=1.0;
    if(lage<30)lifeAgeF=0.7; else if(lage<40)lifeAgeF=1.0; else if(lage<50)lifeAgeF=1.7; else if(lage<60)lifeAgeF=3.0; else if(lage<66)lifeAgeF=4.5; else lifeAgeF=6.0;
    var tobRaw=norm(body.tobacco);
    var tob=(body.tobacco===true||tobRaw.indexOf("ja")>=0||tobRaw.indexOf("yes")>=0||tobRaw.indexOf("rauch")>=0||tobRaw.indexOf("smok")>=0);
    var tobF=tob?1.6:1.0;
    var termF=1+Math.max(0,(term-10))*0.015;
    mid=sa*prod.rate*lifeAgeF*tobF*termF;
    rationale=prod.ProductName+", "+lage+" Jahre, Summe "+sa+" Euro, "+term+" Jahre.";
  }
}

if(missing.length>0){
  return [{ json: {
    status:"NeedsReview", line:line,
    recommended_product: prod?{ProductCode:prod.ProductCode,ProductName:prod.ProductName}:null,
    estimate:null, indicative_range:null,
    rationale:"Es fehlen noch Angaben fuer eine genaue Schaetzung.",
    missing_fields:missing, next_step:"collect_missing", offer_channel:null, disclaimer:DISC
  } }];
}

var est=round10(mid);
return [{ json: {
  status:"Qualified", line:line,
  recommended_product:{ProductCode:prod.ProductCode,ProductName:prod.ProductName},
  estimate:est,
  indicative_range:{ low:round10(mid*0.96), high:round10(mid*1.04), currency:"EUR", per:"year" },
  rationale:rationale, missing_fields:[],
  next_step:"offer_consultation_booking",
  offer_channel:"email_offer_sms_link",
  disclaimer:DISC
} }];
